record.field:
if records:
    non_monetary_tag = env['account.account']._get_non_monetary_tag()
    if non_monetary_tag:
        non_monetary_types = env['account.account'].NON_MONETARY_ACCOUNT_TYPES
        accounts_to_tag = records.filtered(
            lambda a: a.account_type in non_monetary_types and non_monetary_tag.id not in a.tag_ids.ids
        )
        if accounts_to_tag:
            accounts_to_tag.write({'tag_ids': [(4, non_monetary_tag.id)]})

if records:
    non_monetary_tag = env['account.account']._get_non_monetary_tag()
    if non_monetary_tag:
        accounts_with_tag = records.filtered(lambda a: non_monetary_tag.id in a.tag_ids.ids)
        if accounts_with_tag:
            accounts_with_tag.write({'tag_ids': [(3, non_monetary_tag.id)]})
